// Tag sentiment result
const result = $input.first().json;
return {
  json: {
    source: 'sentiment',
    data: result
  }
};

// Tag entities result
const result = $input.first().json;
return {
  json: {
    source: 'entities',
    data: result
  }
};

// Tag OpenAI result
const result = $input.first().json;
return {
  json: {
    source: 'openai',
    data: result
  }
};

// ============================================
// MERGE RESULTS - Analyze Message
// ============================================

const items = $input.all();
const prevData = $('Validate Input').first().json;
const text = prevData.text;
const options = prevData.options;
const startTime = prevData.startTime;

// --- Context fields for traceability ---
const userId = prevData.user_id;
const guildId = prevData.guild_id;
const userRequest = prevData.user_request;

// Default values
const DEFAULT_PRIORITY = { level: 'medium', score: 0.5, indicators: [], requires_confirmation: false };
const DEFAULT_LANGUAGE = { code: 'unknown', confidence: 0 };

// Find results by source tag
let sentimentData = null;
let entitiesData = null;
let openaiData = null;

for (const item of items) {
  const source = item.json.source;
  const data = item.json.data;

  if (source === 'sentiment') {
    sentimentData = data;
  } else if (source === 'entities') {
    entitiesData = data;
  } else if (source === 'openai') {
    openaiData = data;
  }
}

// Process sentiment
let sentimentResult = null;
try {
  if (sentimentData && sentimentData.documentSentiment) {
    const ds = sentimentData.documentSentiment;
    sentimentResult = {
      label: ds.score > 0.2 ? 'positive' : ds.score < -0.2 ? 'negative' : 'neutral',
      score: ds.score,
      magnitude: ds.magnitude,
      confidence: Math.min(1, Math.abs(ds.score) + ds.magnitude / 2)
    };
  } else if (sentimentData && sentimentData.error) {
    sentimentResult = { label: 'neutral', score: 0, magnitude: 0, confidence: 0, error: sentimentData.error.message || 'Google API error' };
  } else {
    sentimentResult = { label: 'neutral', score: 0, magnitude: 0, confidence: 0, error: 'No sentiment data' };
  }
} catch (e) {
  sentimentResult = { label: 'neutral', score: 0, magnitude: 0, confidence: 0, error: 'Sentiment processing failed: ' + e.message };
}

// Process entities
let entitiesResult = [];
try {
  if (entitiesData && entitiesData.entities) {
    entitiesResult = entitiesData.entities.map(e => ({
      type: e.type,
      value: e.name,
      salience: e.salience,
      metadata: e.metadata || {}
    }));
  } else if (entitiesData && entitiesData.error) {
    entitiesResult = [];
  }
} catch (e) {
  entitiesResult = [];
}

// Process OpenAI (intents, priority, language)
let intentsResult = [];
let priorityResult = { ...DEFAULT_PRIORITY };
let languageResult = { ...DEFAULT_LANGUAGE };

try {
  if (openaiData && openaiData.choices && openaiData.choices[0]) {
    const content = openaiData.choices[0].message.content;
    const parsed = JSON.parse(content);

    // Handle intents array - ensure it's always an array
    if (Array.isArray(parsed.intents) && parsed.intents.length > 0) {
      intentsResult = parsed.intents;
    } else if (parsed.intent) {
      // Handle single intent format
      intentsResult = [parsed.intent];
    } else {
      intentsResult = [{ type: 'unknown', action: 'unknown', target: null, confidence: 0.1, reasoning: 'No intent detected' }];
    }

    // Handle priority - always provide defaults
    if (parsed.priority && typeof parsed.priority === 'object') {
      priorityResult = {
        level: parsed.priority.level || 'medium',
        score: typeof parsed.priority.score === 'number' ? parsed.priority.score : 0.5,
        indicators: Array.isArray(parsed.priority.indicators) ? parsed.priority.indicators : [],
        requires_confirmation: parsed.priority.requires_confirmation === true
      };
    }

    // Handle language - always provide defaults
    if (parsed.language && typeof parsed.language === 'object') {
      languageResult = {
        code: parsed.language.code || 'unknown',
        confidence: typeof parsed.language.confidence === 'number' ? parsed.language.confidence : 0
      };
    }
  } else if (openaiData && openaiData.error) {
    intentsResult = [{ type: 'error', action: 'unknown', target: null, confidence: 0, reasoning: 'OpenAI API error: ' + (openaiData.error.message || 'Unknown') }];
  } else {
    intentsResult = [{ type: 'error', action: 'unknown', target: null, confidence: 0, reasoning: 'No OpenAI response received' }];
  }
} catch (e) {
  intentsResult = [{ type: 'error', action: 'unknown', target: null, confidence: 0, reasoning: 'OpenAI parsing failed: ' + e.message }];
}

// --- Build _trace for Langfuse observability ---
const llmResponse = openaiData?.choices?.[0]?.message?.content || null;

const _trace = {
  llm_response: llmResponse,
  providers: ['google', 'openai'],
  parallel: true,
  latency_ms: Date.now() - startTime,
  user_id: userId,
  guild_id: guildId,
  user_request: userRequest,
  text: text
};

// Build final response - always include all fields
return {
  json: {
    success: true,
    data: {
      text: text,
      analysis: {
        sentiment: sentimentResult,
        intents: intentsResult,
        entities: entitiesResult,
        priority: priorityResult,
        language: languageResult
      }
    },
    meta: {
      providers: {
        sentiment: 'google-cloud-nlp',
        entities: 'google-cloud-nlp',
        intents: 'openai-gpt4o-mini',
        priority: 'openai-gpt4o-mini',
        language: 'openai-gpt4o-mini'
      },
      processing_time_ms: Date.now() - startTime
    },
    user_id: userId,
    guild_id: guildId,
    user_request: userRequest,
    _trace: _trace
  }
};

// ============================================
// VALIDATION INPUT - Analyze Message
// ============================================

